h1.title{font-family:'Bodoni Moda',serif;font-weight:500;font-size:clamp(3.2rem,13vw,11rem);line-height:.88;letter-spacing:-.01em;margin:.3em 0 .1em}
h1.title em{font-style:italic;color:var(--burgundy);font-weight:400}
.deck{font-size:clamp(1.1rem,2.3vw,1.55rem);max-width:46ch;color:var(--amber-deep);margin-top:1.2rem;font-family:'Bodoni Moda',serif;font-style:italic}
.hero-meta{margin-top:3rem;display:flex;flex-wrap:wrap;gap:2.5rem;font-family:'IBM Plex Mono',monospace;font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;color:var(--amber-deep)}
.hero-meta span b{display:block;font-size:1.5rem;font-family:'Bodoni Moda',serif;letter-spacing:0;text-transform:none;color:var(--ink);font-weight:600}
.glass{position:absolute;top:9%;right:9%;font-size:7rem;opacity:.1;transform:rotate(-6deg)}

/* ---------- HEALTH BANNER ---------- */
.banner{background:var(--burgundy);color:var(--paper);padding:1.1rem clamp(1.5rem,7vw,10rem);font-size:.92rem;display:flex;gap:.8rem;align-items:center;border-bottom:2px solid var(--ink)}
.banner b{font-family:'IBM Plex Mono',monospace;letter-spacing:.1em;text-transform:uppercase;font-size:.7rem}

/* ---------- NAV ---------- */
nav.toc{position:sticky;top:0;z-index:50;background:var(--ink);color:var(--paper);display:flex;gap:0;overflow-x:auto;border-bottom:2px solid var(--ink);font-family:'IBM Plex Mono',monospace;font-size:.67rem;letter-spacing:.13em;text-transform:uppercase}
nav.toc a{color:var(--paper);text-decoration:none;padding:1rem 1.2rem;white-space:nowrap;border-right:1px solid rgba(236,228,214,.14);transition:.25s;flex-shrink:0}
nav.toc a:hover{background:var(--amber);color:var(--ink)}

/* ---------- SECTIONS ---------- */
section{padding:clamp(3rem,8vw,7rem) clamp(1.5rem,7vw,10rem);border-bottom:1px solid var(--line)}
.sec-head{display:flex;align-items:baseline;gap:1.2rem;margin-bottom:1.8rem}
.sec-num{font-family:'IBM Plex Mono',monospace;font-size:.82rem;color:var(--gold);letter-spacing:.2em}
h2{font-family:'Bodoni Moda',serif;font-weight:500;font-size:clamp(2rem,5vw,3.6rem);line-height:1;letter-spacing:-.01em}
h3{font-family:'Bodoni Moda',serif;font-weight:600;font-size:1.6rem;margin:2rem 0 .6rem;color:var(--amber-deep)}
p{max-width:68ch;margin-bottom:1.1rem}
.lead{font-size:1.22rem;max-width:60ch}
.dropcap::first-letter{font-family:'Bodoni Moda',serif;font-weight:500;float:left;font-size:4.8rem;line-height:.76;padding:.06em .12em 0 0;color:var(--burgundy)}

/* timeline */
.timeline{border-left:2px solid var(--line);margin:2rem 0 0}
.tl-item{position:relative;padding:0 0 2rem 2.2rem}
.tl-item::before{content:"";position:absolute;left:-7px;top:.45rem;width:12px;height:12px;border-radius:50%;background:var(--amber);border:2px solid var(--ink)}
.tl-year{font-family:'IBM Plex Mono',monospace;font-size:.76rem;letter-spacing:.18em;color:var(--gold)}

/* cards */
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:1.2rem;margin-top:2rem}
.card{background:var(--paper-2);border:1px solid var(--line);padding:1.6rem 1.5rem;position:relative;overflow:hidden}
.card::after{content:"";position:absolute;top:0;right:0;width:44px;height:44px;background:var(--amber);clip-path:polygon(100% 0,0 0,100% 100%)}
.card .ic{font-size:1.7rem;display:block;margin-bottom:.5rem}
.card h4{font-family:'Bodoni Moda',serif;font-size:1.25rem;margin-bottom:.3rem;font-weight:600}
.card p{font-size:.95rem;margin:0}

/* spectrum */
.spectrum{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:0;margin-top:2rem;border:2px solid var(--ink)}
.swatch{padding:1.4rem 1.1rem;color:#fff;min-height:150px;display:flex;flex-direction:column;justify-content:flex-end;border-right:1px solid rgba(255,255,255,.18)}
.swatch:last-child{border-right:none}
.swatch .lbl{font-family:'IBM Plex Mono',monospace;font-size:.62rem;letter-spacing:.14em;text-transform:uppercase;opacity:.85}
.swatch .nm{font-family:'Bodoni Moda',serif;font-size:1.4rem;font-weight:600;line-height:1}
.swatch small{font-size:.82rem;opacity:.92;margin-top:.3rem}

/* methods */
.method{margin-top:3.5rem;border:2px solid var(--ink);background:var(--paper-2);box-shadow:8px 8px 0 var(--shadow)}
.method-top{display:grid;grid-template-columns:1fr}
@media(min-width:840px){.method-top{grid-template-columns:1.1fr 1fr}}
.method-id{padding:2rem 2rem 1.5rem;border-bottom:2px solid var(--ink)}
@media(min-width:840px){.method-id{border-bottom:none;border-right:2px solid var(--ink)}}
.method-id .tag{font-family:'IBM Plex Mono',monospace;font-size:.67rem;letter-spacing:.2em;text-transform:uppercase;color:var(--gold)}
.method-id h3{margin:.3rem 0 .8rem;font-size:2.1rem;color:var(--ink)}
.specs{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1rem}
.spec{font-family:'IBM Plex Mono',monospace;font-size:.63rem;letter-spacing:.05em;text-transform:uppercase;background:var(--ink);color:var(--paper);padding:.35rem .6rem}
.spec.alt{background:transparent;color:var(--ink);border:1px solid var(--ink)}
.method-blurb{padding:2rem}
.method-blurb p{font-size:1rem}

.steps{counter-reset:step;list-style:none;padding:1.8rem 2rem 2rem;border-top:2px dashed var(--line)}
.steps li{counter-increment:step;position:relative;padding-left:3rem;margin-bottom:1rem;font-size:1rem;max-width:64ch}
.steps li::before{content:counter(step,decimal-leading-zero);position:absolute;left:0;top:0;font-family:'IBM Plex Mono',monospace;font-size:.85rem;color:var(--paper);background:var(--burgundy);width:2rem;height:2rem;display:flex;align-items:center;justify-content:center;border-radius:50%}

.tradeoffs{display:grid;grid-template-columns:1fr;border-top:2px solid var(--ink)}
@media(min-width:680px){.tradeoffs{grid-template-columns:1fr 1fr}}
.pros,.cons{padding:1.6rem 2rem}
.pros{background:rgba(184,118,42,.12)}
.cons{background:rgba(107,36,54,.08);border-top:1px solid var(--line)}
@media(min-width:680px){.cons{border-top:none;border-left:1px solid var(--ink)}}
.toff-h{font-family:'IBM Plex Mono',monospace;font-size:.7rem;letter-spacing:.2em;text-transform:uppercase;margin-bottom:.8rem}
.pros .toff-h{color:var(--amber-deep)}
.cons .toff-h{color:var(--burgundy)}
.tradeoffs ul{list-style:none}
.tradeoffs li{font-size:.95rem;padding:.3rem 0 .3rem 1.4rem;position:relative}
.pros li::before{content:"+";position:absolute;left:0;color:var(--amber-deep);font-weight:700}
.cons li::before{content:"–";position:absolute;left:0;color:var(--burgundy);font-weight:700}

blockquote{font-family:'Bodoni Moda',serif;font-style:italic;font-size:clamp(1.4rem,3.4vw,2.3rem);line-height:1.3;max-width:26ch;margin:3rem auto;text-align:center;color:var(--amber-deep);position:relative;font-weight:400}
blockquote::before{content:"❧";font-size:2rem;color:var(--amber);display:block;margin-bottom:.4rem}

table.ratio{width:100%;border-collapse:collapse;margin-top:2rem;font-size:.95rem}
table.ratio th,table.ratio td{border:1px solid var(--line);padding:.7rem 1rem;text-align:left}
table.ratio th{background:var(--ink);color:var(--paper);font-family:'IBM Plex Mono',monospace;font-size:.65rem;letter-spacing:.1em;text-transform:uppercase;font-weight:400}
table.ratio tr:nth-child(even){background:var(--paper-2)}
table.ratio td:first-child{font-weight:700;color:var(--amber-deep)}

footer{padding:4rem clamp(1.5rem,7vw,10rem);background:var(--ink);color:var(--paper);text-align:center}
footer .big{font-family:'Bodoni Moda',serif;font-style:italic;font-size:clamp(1.5rem,4vw,2.4rem);margin-bottom:1rem}
footer p{margin:0 auto 1rem;color:#cabda4;font-size:.95rem;max-width:60ch}
footer .resources{font-family:'IBM Plex Mono',monospace;font-size:.72rem;letter-spacing:.1em;color:var(--gold);margin-top:1.5rem}

.reveal{opacity:0;transform:translateY(28px);transition:opacity .7s ease,transform .7s ease}
.reveal.in{opacity:1;transform:none}
